def is_subset_sum(set, n, sum):
    """Write a function to determine if there is a subset of the given set with sum equal to the given sum."""
    elements = list(set)
    if n is None:
        count = len(elements)
    else:
        count = int(n)
    if count < 0:
        count = 0
    elif count > len(elements):
        count = len(elements)
    elements = elements[:count]

    if sum == 0:
        return True

    # Bitset DP for the common case of non-negative integers: bit ``s``
    # of ``bits`` is set exactly when some subset sums to ``s``. Keeping
    # only bits up to ``sum`` bounds the work by the target, not by the
    # number of distinct subset sums.
    if (
        isinstance(sum, int)
        and 0 < sum <= 1_000_000
        and all(isinstance(value, int) and value >= 0 for value in elements)
    ):
        bits = 1
        mask = (1 << (sum + 1)) - 1
        for value in elements:
            if value <= sum:
                bits |= (bits << value) & mask
                if (bits >> sum) & 1:
                    return True
        return bool((bits >> sum) & 1)

    # General case (e.g. negative or non-integer values): track all
    # reachable sums. When every value is non-negative, sums above the
    # target can never come back down to it and can be pruned.
    try:
        can_prune = sum > 0 and all(value >= 0 for value in elements)
    except TypeError:
        can_prune = False

    reachable = {0}
    for value in elements:
        if can_prune:
            new_sums = {
                current + value
                for current in reachable
                if current + value <= sum
            }
        else:
            new_sums = {current + value for current in reachable}
        reachable.update(new_sums)
        if sum in reachable:
            return True
    return sum in reachable
